/**
 * EZRAB MARKET PRICES 2026 — riset harga pasar marketplace Indonesia.
 * ==================================================================
 *
 * Input source MARKET_2026 (pipeline harga EZRAB 2026). Satu baris per
 * (nama mentah AHSP, satuan) — satu target adopsi bisa punya beberapa
 * baris bila nama mentahnya bervariasi di AHSP kanonis (varian didedup
 * sesudah normalisasi nama runtime). Harga adopsi = median penawaran
 * (DIRECT) atau harga turunan bersumber (BULK_DERIVED / DERIVED).
 *
 * PROVENANCE: setiap baris membawa SEMUA penawaran yang diriset
 * (penjual + marketplace + URL + harga + tanggal observasi) — record
 * priceMaster hanya membawa supplier + sourceRecordId (MKT-xxx), dan
 * penawaran lengkap ditelusur lewat ID itu di file ini.
 *
 * MARKET_REFERENCE, BUKAN harga resmi AHSP. Riset 16 Nov 2026
 * (baris COMPONENT + MIXED_AVG: 17 Nov 2026).
 *
 * Aturan owner 17 Nov 2026: item CAMPURAN didekomposisi — harga mix =
 * RATA-RATA harga komponennya. Paku 5+7 cm (R007/R050/R098) diadopsi
 * sebagai MIXED_AVG Rp23.000/kg = (Rp23.000 + Rp23.000)/2; komponennya
 * (Paku 5 cm, Paku 7 cm) disimpan sendiri di MARKET_COMPONENT_ITEMS
 * (kind 'COMPONENT') dan di-emit pipeline sebagai record standalone
 * COMPONENT_REF, tanpa ikatan komponen kanonis. Pengecualian: desain
 * campuran beton per m3 tetap memakai harga pasar langsung ready-mix
 * (komponen beda satuan + proporsi desain — tidak dirata-rata).
 *
 * Sumber: adoption-dataset.json (82 target adopsi) + research-list.json
 * (varian nama mentah + kode AHSP) + merged-final.json (penawaran) +
 * component-prices.json (baris COMPONENT + penawaran MIXED_AVG) —
 * program EZRAB-AHSP-HARGA-ADOPSI-2026-11-17. Dibangkitkan oleh
 * generate-market-input.py di folder program yang sama; JANGAN edit
 * manual — perbaiki dataset/generator lalu regenerasi.
 *
 * RONDE 2 (17 Nov 2026, program EZRAB-AHSP-HARGA-KOREKSI-2026-11-17):
 * dibangkitkan ulang oleh generate-market-input-r2.py dari merge-r2.json
 * (508 entri) + binding probe ronde 2. Baris R1 dipertahankan kecuali
 * aksi V3 SS9.2 (7 hapus redundan, 17 rename kosmetik), 5 koreksi R1
 * (R101/R089/R057/R078/R044, corrections-v2) dan repurpose MKT-R077
 * (OWNER-01: Pasir Pasang M.05.d.3 kg→m³, Rp375→Rp240.000). Target yang
 * sudah resolve via record resmi CK/BM atau record pasar yang ada TIDAK
 * mendapat baris baru (record pasar untuk pasangan yang tercakup record
 * resmi prioritas 1 adalah mati — lihat implementation-r2.md). Satu
 * baris (R091) memakai priceSource 'AHSP_SDA_DOC' — harga tercetak di
 * dokumen AHSP SDA, BUKAN harga pasar.
 */

export interface MarketOffer {
  seller: string;        // nama toko/penjual
  marketplace: string;   // sumber penawaran verbatim (Tokopedia / Shopee / situs supplier)
  url: string;           // URL penawaran spesifik ('' bila riset tanpa URL — 61 penawaran R2)
  price: number;         // harga penawaran (IDR, per sellUnit)
  observedAt: string;    // tanggal observasi ('2026-11-16' / '2026-11-17')
  sellUnit: string;      // satuan jual penawaran verbatim
  unitMatch: boolean;    // true bila penawaran masuk himpunan median (satuan cocok DAN varian produk cocok)
  component?: string;    // HANYA di penawaran baris MIXED_AVG: komponen asal penawaran
  notes?: string;        // catatan riset per penawaran (bila ada)
}

export interface MarketPriceItem {
  id: string;            // 'MKT-R003' / 'MKT-COMP-5CM' — menjadi sourceRecordId; STABIL, jangan diubah
  kind?: 'COMPONENT';    // HANYA untuk baris dekomposisi item campuran (di MARKET_COMPONENT_ITEMS)
  code: string;          // kode komponen AHSP bila diketahui (mis. 'M.23'); '' bila tidak
  name: string;          // nama komponen AHSP verbatim (target NAME_UNIT / NAME_KEY)
  category: 'MATERIAL';  // adopsi ini hanya material
  specification: string; // spesifikasi penawaran ('' bila tidak ada di luar nama)
  unit: string;          // HARUS sama dengan satuan component key target (kg, m3, ...)
  price: number;         // nilai ADOPSI: median penawaran, atau harga turunan curah
  location: string;      // 'Nasional'
  supplier: string;      // penjual penawaran median (DIRECT) / sumber turunan (DERIVED)
  periodVersion: '2026-11';
  lastUpdated: string;   // tanggal riset baris ini ('2026-11-16'; COMPONENT/MIXED_AVG '2026-11-17') — juga menjadi retrievedAt record
  priceSource: 'Riset Harga Pasar EZRAB 2026' | 'AHSP_SDA_DOC';  // AHSP_SDA_DOC = harga tercetak dokumen AHSP SDA (R091, ronde 2)
  basis: 'MEDIAN' | 'BULK_DERIVED' | 'DERIVED' | 'MIXED_AVG' | 'AHSP_DOC';  // DERIVED = konversi bersumber; MIXED_AVG = rata-rata komponen (formula owner); AHSP_DOC = harga dokumen (R091)
  basisNote: string;     // rumus lengkap (median / turunan curah / konversi)
  offers: MarketOffer[]; // SEMUA penawaran yang diriset (provenance lengkap)
}

